function nav(locale, route){const t=common[locale], prefix=locale==='zh'?'/zh':'';return `<a class="skip-link" href="#main">${locale==='en'?'Skip to content':'跳至主要内容'}</a><div class="topbar"><div class="container topbar-inner"><span>${t.top}</span><span>UEN 202539469C · <a href="tel:${phoneRaw}">${phone}</a></span></div></div><header class="header"><div class="container nav"><a class="logo" href="${prefix}/">NANO<span>FIX</span><b></b></a><nav class="nav-links" data-nav aria-label="${locale==='en'?'Primary navigation':'主要导航'}"><a href="${prefix}/" ${route==='/'?'aria-current="page"':''}>${t.home}</a><div class="nav-group"><a href="${prefix}/services/" ${route.startsWith('/services')?'aria-current="page"':''}>${t.services}</a><div class="submenu"><a href="${prefix}/services/high-temperature-steam-chemical-cleaning/">${locale==='en'?'Steam Chemical Cleaning':'高温蒸汽化学清洗'}</a><a href="${prefix}/services/steam-vs-standard-aircon-cleaning/">${locale==='en'?'Steam vs Standard Cleaning':'蒸汽化学清洗与普通清洗'}</a><a href="${prefix}/services/why-steam-chemical-cleaning/">${locale==='en'?'Why Choose Steam Cleaning':'为什么选择蒸汽化学清洗'}</a><a href="${prefix}/services/pricing-packages/">${locale==='en'?'Pricing & Packages':'价格与套餐'}</a></div></div><a href="${prefix}/faq-reviews/" ${route.startsWith('/faq-reviews')?'aria-current="page"':''}>${t.faq}</a><a href="${prefix}/contact/" ${route==='/contact/'?'aria-current="page"':''}>${t.contact}</a><a class="lang-link" href="${switchPath(route,locale)}" lang="${locale==='en'?'zh-SG':'en-SG'}">${t.chinese}</a></nav><a class="button button-orange" href="${prefix}/contact/#booking">${t.book}</a><button class="menu-button" type="button" data-menu aria-expanded="false" aria-label="Menu">☰</button></div></header>`}
function footer(locale){const t=common[locale],p=locale==='zh'?'/zh':'';return `<section class="section"><div class="container"><div class="cta"><div><h2>${t.ctaTitle}</h2><p>${t.ctaText}</p></div><a class="button button-orange" href="${p}/contact/#booking">${t.book} →</a></div></div></section><footer class="footer"><div class="container"><div class="footer-grid"><div><a class="logo" href="${p}/">NANO<span>FIX</span><b></b></a><p>${locale==='en'?'High-temperature steam aircon chemical cleaning for homes and commercial properties in Singapore.':'为新加坡住宅和商业场所提供高温蒸汽空调化学清洗。'}</p><a href="tel:${phoneRaw}">${phone}</a><a href="mailto:nanofixac@gmail.com">nanofixac@gmail.com</a></div><div><h3>${t.serviceLabel}</h3><a href="${p}/services/high-temperature-steam-chemical-cleaning/">${locale==='en'?'Steam Chemical Cleaning':'高温蒸汽化学清洗'}</a><a href="${p}/services/steam-vs-standard-aircon-cleaning/">${locale==='en'?'Service Comparison':'清洗服务对比'}</a><a href="${p}/services/pricing-packages/">${locale==='en'?'Pricing & Packages':'价格与套餐'}</a><a href="${p}/faq-reviews/before-after/">${locale==='en'?'Before & After':'清洗前后案例'}</a></div><div><h3>${t.quick}</h3><a href="${p}/faq-reviews/">${t.faq}</a><a href="${p}/faq-reviews/customer-reviews/">${locale==='en'?'Customer Reviews':'客户评论'}</a><a href="${p}/contact/">${t.contact}</a><a href="${p}/privacy/">${t.privacy}</a><a href="${p}/terms/">${t.terms}</a></div><div><h3>${t.related}</h3><a class="friend-link" href="https://nanofixsg.com" target="_blank" rel="noopener noreferrer"><strong>${t.leak}</strong><br><small>${t.leakDesc}</small></a><p>16 Raffles Quay #41-01<br>Hong Leong Building<br>Singapore 048581</p></div></div><div class="footer-bottom"><span>${t.copyright}</span><span>UEN 202539469C</span></div></div></footer><a class="whatsapp-float" href="https://wa.me/${phoneRaw}?text=${encodeURIComponent(locale==='en'?'Hello NANOFIX, I would like to enquire about high-temperature steam aircon chemical cleaning.':'您好 NANOFIX，我想咨询高温蒸汽空调化学清洗。')}" target="_blank" rel="noopener noreferrer" aria-label="${t.whatsapp}"><span>WA</span><span>${t.whatsapp}</span></a><script src="/assets/site.js" defer></script>`}
function serviceCards(locale){const p=locale==='zh'?'/zh':'';const items=locale==='en'?[['01','High-Temperature Steam Chemical Cleaning','Chemical pre-treatment, controlled steam and contained rinsing for accessible internal components.','high-temperature-steam-chemical-cleaning','hero-steam-cleaning.webp'],
['02','Steam vs Standard Cleaning','Compare cleaning depth, component scope, suitability, working time and price.','steam-vs-standard-aircon-cleaning','steam-vs-standard.webp'],
['03','Why Choose Steam Cleaning','Hygiene-focused, in-situ deep cleaning with less dismantling where the unit condition allows.','why-steam-chemical-cleaning','case-in-situ-steam-cleaning.webp'],
['04','Pricing & Packages','Clear quotations based on unit type, quantity, buildup, access and required dismantling.','pricing-packages','pricing-consultation.webp']]:[['01','高温蒸汽化学清洗','化学预处理、可控蒸汽及封闭式冲洗，深度处理可接触内部部件。','high-temperature-steam-chemical-cleaning','hero-steam-cleaning.webp'],
['02','蒸汽化学清洗与普通清洗','比较清洗深度、部件范围、适用情况、施工时间和价格。','steam-vs-standard-aircon-cleaning','steam-vs-standard.webp'],
['03','为什么选择蒸汽化学清洗','在机型及状况允许时，以原位深洗减少大拆，并加强卫生清洁。','why-steam-chemical-cleaning','case-in-situ-steam-cleaning.webp'],
['04','价格与套餐','根据机型、数量、积垢、施工条件及拆卸要求清楚报价。','pricing-packages','pricing-consultation.webp']];return `<div class="cards service-visual-cards">${items.map(i=>`<article class="card visual-card"><img src="${asset(i[4])}" alt="${i[1]}" width="1200" height="750" loading="lazy"><div class="visual-card-copy"><div class="number">${i[0]}</div><h3>${i[1]}</h3><p>${i[2]}</p><a class="text-link" href="${p}/services/${i[3]}/">${locale==='en'?'View details':'查看详情'}</a></div></article>`).join('')}</div>`}
function home(locale){const zh=locale==='zh',p=zh?'/zh':'';const benefits=zh?[['卫生深洗','可控高温蒸汽直接作用于可接触表面，帮助降低细菌、霉菌及异味源；这是专业卫生清洁，不宣称医疗级灭菌。'],['减少大拆','多数合适机型可保持室内机在墙上，仅拆过滤网、外盖及可接触部件；特殊机型或严重积垢另行评估。'],['更彻底处理积垢','适用的化学预处理先松动油膜、灰尘及有机残留，再以蒸汽和封闭式冲洗带走污物。'],['按保修要求施工','不改动密封制冷系统，保护电气区域并清洗后测试；厂家保修条款因品牌和机型而异，应按原条款确认。']]:[['Hygiene-focused cleaning','Controlled steam acts directly on accessible surfaces to help reduce bacteria, mould and odour sources. This is professional hygienic cleaning—not a medical sterilisation claim.'],['Less dismantling','Suitable units can often remain wall-mounted while filters, covers and accessible parts are removed. Special designs or heavy buildup may need more dismantling.'],['Thorough residue removal','Suitable chemical pre-treatment loosens oily film, embedded dust and organic residue before steam and contained rinsing carry the soil away.'],['Warranty-conscious process','We avoid altering sealed refrigeration systems, protect electrical areas and test after cleaning. Manufacturer warranty terms still vary by brand and model.']];return `<main id="main"><section class="hero hero-photo"><img class="hero-photo-bg" src="${asset('hero-nanofixac-steam.webp')}" alt="${zh?'NANOFIXAC技术人员在新加坡公寓使用高温蒸汽设备清洗空调':'NANOFIXAC technician using professional high-temperature steam equipment to clean an aircon in a Singapore condominium'}" width="1920" height="1080" fetchpriority="high"><div class="hero-photo-shade"></div><div class="container hero-overlay"><div class="hero-copy"><div class="eyebrow">${zh?'新加坡专业空调深度清洗':'Professional deep aircon cleaning in Singapore'}</div><h1>${zh?'高温蒸汽<br><span>空调化学清洗</span>':'HIGH-TEMPERATURE STEAM<br><span>AIRCON CHEMICAL CLEANING</span>'}</h1><p>${zh?'化学预处理、可控高温蒸汽和封闭式冲洗，深入处理蒸发器、风轮、排水盘及可接触排水系统。':'Chemical pre-treatment, controlled high-temperature steam and contained rinsing for evaporator coils, blower wheels, drain pans and accessible drainage.'}</p><div class="hero-actions"><a class="button button-orange" href="${p}/contact/#booking">${zh?'预约清洗':'BOOK A CLEANING'} →</a><a class="button button-ghost" href="${p}/services/high-temperature-steam-chemical-cleaning/">${zh?'查看清洗范围':'SEE WHAT IS INCLUDED'}</a></div><div class="trust-row"><span>${zh?'减少大拆':'Less dismantling'}</span><span>${zh?'卫生深洗':'Hygiene-focused'}</span><span>${zh?'清洗后测试':'Post-clean testing'}</span></div></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">${zh?'为什么不同':'Why it is different'}</div><h2>${zh?'化学处理与蒸汽<br>各有明确作用。':'Chemical treatment and steam,<br>each with a clear purpose.'}</h2></div><p>${zh?'不用夸张承诺，用清楚的施工逻辑解释为什么它比普通表面清洗更深入。':'A clear process explains why this goes deeper than routine surface cleaning—without exaggerated promises.'}</p></div><div class="feature-stack"><article class="feature-row">${img('chemical-steam-process.webp',zh?'NANOFIXAC技术人员对空调进行化学预处理和可控蒸汽清洗':'NANOFIXAC technician applying aircon chemical pre-treatment and controlled steam')}<div class="prose"><div class="eyebrow">${zh?'第一步与第二步':'Loosen, then lift'}</div><h2>${zh?'先松动顽固残留，<br>再用热力深入清洁。':'Loosen stubborn soil.<br>Then clean with controlled heat.'}</h2><p>${zh?'适用的清洗处理帮助分解附着在翅片、风轮和排水盘上的油膜、灰尘与有机积垢；受控蒸汽进入可接触缝隙，清洗罩和排水管将污水导入容器。':'A suitable cleaning treatment helps loosen oily film, embedded dust and organic buildup on fins, blower and drain pan. Controlled steam reaches accessible gaps while the wash bag contains runoff.'}</p><a class="text-link" href="${p}/services/high-temperature-steam-chemical-cleaning/">${zh?'查看完整六步流程':'View the complete six-step process'}</a></div></article><article class="feature-row feature-row-reverse">${img('in-situ-steam-cleaning.webp',zh?'空调保持在墙上进行原位高温蒸汽深洗':'Wall-mounted aircon receiving in-situ high-temperature steam deep cleaning')}<div class="prose"><div class="eyebrow">${zh?'减少大拆':'In-situ where suitable'}</div><h2>${zh?'机型允许时，<br>空调保持原位深洗。':'A deep clean without taking<br>the whole unit off the wall.'}</h2><p>${zh?'过滤网、外盖和需要清洗的可接触部件会按情况拆卸，室内机主体可在适合时保持原位。这样减少对密封制冷系统的干预；如污染严重或结构受限，我们会先说明额外拆卸要求。':'Filters, covers and accessible parts are removed as needed while the indoor unit can remain mounted where suitable. This reduces intervention around sealed systems; extra dismantling is explained first when condition or design requires it.'}</p><a class="text-link" href="${p}/services/why-steam-chemical-cleaning/">${zh?'了解适用情况与限制':'See when this method is suitable'}</a></div></article></div></div></section><section class="section section-mint"><div class="container"><div class="section-heading"><div><div class="eyebrow">${zh?'核心好处':'Key benefits'}</div><h2>${zh?'客户关心的四件事，<br>直接说明。':'Four practical benefits,<br>clearly explained.'}</h2></div></div><div class="benefit-grid">${benefits.map((b,i)=>`<article class="benefit-card"><span>0${i+1}</span><h3>${b[0]}</h3><p>${b[1]}</p></article>`).join('')}</div></div></section><section class="section section-navy"><div class="container split process-split"><div>${img('post-clean-inspection.webp',zh?'清洗后检查空调翅片并测量送风':'Post-clean inspection of aircon fins and airflow')}</div><div><div class="section-heading"><div><div class="eyebrow" style="color:#6bd6a4">${zh?'六步施工流程':'Six-step process'}</div><h2>${zh?'防护、深洗、测试。':'Protect. Deep-clean. Test.'}</h2></div></div><div class="steps steps-compact">${(zh?['检查制冷、风量、噪音及排水','保护墙面、地面、电气区及家具','拆卸过滤网、外盖和可接触部件','使用适合的空调化学清洗处理','进行可控高温蒸汽和封闭式冲洗','重新组装，测试运行、风量及排水']:['Check cooling, airflow, noise and drainage','Protect walls, floors, electrical areas and furniture','Remove filters, covers and accessible parts','Apply suitable aircon chemical treatment','Use controlled steam and contained rinsing','Reassemble, test operation, airflow and drainage']).map(x=>`<div class="step"><h3>${x}</h3></div>`).join('')}</div></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">${zh?'完整服务目录':'Explore the service'}</div><h2>${zh?'从作用到价格，<br>每个问题都有独立页面。':'From benefits to pricing,<br>every question has a clear page.'}</h2></div></div>${serviceCards(locale)}</div></section><section class="section section-mint"><div class="container split"><div>${img('steam-vs-standard.webp',zh?'普通空调清洗与高温蒸汽化学清洗对比':'Standard aircon servicing compared with high-temperature steam chemical cleaning')}</div><div class="prose"><div class="eyebrow">${zh?'如何选择':'Choose the right clean'}</div><h2>${zh?'普通保养还是<br>蒸汽化学清洗？':'Standard servicing or<br>steam chemical cleaning?'}</h2><p>${zh?'定期保养适合内部较干净、没有异味或风量问题的空调；当顽固积垢、霉味或风量受阻反复出现时，深度清洗更有针对性。':'Routine servicing suits a clean, well-maintained unit. A deeper clean is more appropriate when stubborn buildup, musty odour or restricted airflow persists.'}</p><a class="button button-green" href="${p}/services/steam-vs-standard-aircon-cleaning/">${zh?'查看完整对比':'SEE THE FULL COMPARISON'} →</a></div></div></section><section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">${zh?'清洗前后':'Before & after'}</div><h2>${zh?'看清楚具体处理<br>哪些内部部件。':'See which internal parts<br>the service addresses.'}</h2></div><p>${zh?'网站案例图用于说明施工位置和预期观感，正式上线后应逐步加入已获客户许可的真实项目记录。':'Website imagery explains the work areas and expected visual outcome. Verified customer-project records should be added after permission is obtained.'}</p></div>${caseCards(locale)}</div></section><section class="section section-mint"><div class="container split faq-intro">${img('post-clean-inspection.webp',zh?'NANOFIXAC技术人员在清洗后检查空调':'NANOFIXAC technician inspecting an aircon after cleaning')}<div><div class="section-heading"><div><div class="eyebrow">FAQ</div><h2>${zh?'客户最常问的问题':'Questions customers ask most.'}</h2></div><a class="text-link" href="${p}/faq-reviews/">${zh?'查看全部问题':'View all questions'}</a></div>${faqMarkup(locale,faqs[locale].slice(0,5))}</div></div></section></main>`}
function homeV2(locale){const zh=locale==='zh';let html=home(locale);const benefits=zh?[['免大拆，保修友好','室内机保持在墙上，风轮保持原位；只拆过滤网、外盖和必要面板，避免改动密封制冷系统。正常保修仍以对应品牌条款为准。'],['化学清洗顽固污垢','适用的空调化学清洗剂帮助分解翅片、原位风轮、出风口和排水盘上的油膜、灰尘及有机积垢，再以封闭式冲洗带走。'],['高温蒸汽杀菌除味','高温蒸汽直接处理可接触表面；在达到适当温度与接触时间时，有助于杀灭细菌、降低霉菌污染并祛除由积垢产生的异味。']]:[['No major dismantling. Warranty-friendly.','The indoor unit stays wall-mounted and the blower wheel remains in place. Only filters, covers and necessary panels are removed, avoiding changes to the sealed refrigeration system. Manufacturer warranty terms still apply.'],['Chemical cleaning for stubborn grime','A suitable aircon chemical cleaner loosens oily film, embedded dust and organic buildup on fins, the in-place blower, air outlet and drain pan before contained rinsing carries it away.'],['High-temperature steam sanitises and removes odour','Steam treats accessible surfaces directly. With suitable temperature and contact time, it helps kill bacteria, reduce mould contamination and remove odour caused by accumulated soil.']];const start=html.indexOf('<div class="benefit-grid">');const marker='</div></div></section><section class="section section-navy">';const end=html.indexOf(marker,start);if(start>=0&&end>=0)html=html.slice(0,start)+`<div class="benefit-grid">${benefits.map((b,i)=>`<article class="benefit-card"><span>0${i+1}</span><h3>${b[0]}</h3><p>${b[1]}</p></article>`).join('')}</div>`+html.slice(end);html=html.replace(zh?'客户关心的四件事，<br>直接说明。':'Four practical benefits,<br>clearly explained.',zh?'三项核心好处，<br>直接说明。':'Three core benefits,<br>clearly explained.');html=html.replace(zh?'过滤网、外盖和需要清洗的可接触部件会按情况拆卸，室内机主体可在适合时保持原位。这样减少对密封制冷系统的干预；如污染严重或结构受限，我们会先说明额外拆卸要求。':'Filters, covers and accessible parts are removed as needed while the indoor unit can remain mounted where suitable. This reduces intervention around sealed systems; extra dismantling is explained first when condition or design requires it.',zh?'室内机保持在墙上，风轮保持原位；只拆过滤网、外盖和必要面板，再用清洗罩进行封闭式原位深洗，避免改动密封制冷系统。':'The indoor unit stays wall-mounted and the blower wheel remains in place. Only filters, covers and necessary panels are removed before contained in-situ cleaning, avoiding changes to the sealed refrigeration system.');html=html.replace(zh?'机型允许时，<br>空调保持原位深洗。':'A deep clean without taking<br>the whole unit off the wall.',zh?'不拆室内机，<br>不拆风轮。':'No indoor-unit removal.<br>No blower-wheel removal.');html=html.replace(zh?'减少大拆':'Less dismantling',zh?'免大拆':'No major dismantling');return html}
function caseCards(locale){const zh=locale==='zh';const items=[['case-coil-before-after.webp',zh?'蒸发器深度清洗':'Evaporator coil deep cleaning',zh?'清除可接触翅片表面的顽固积尘和残留物。':'Removing stubborn buildup from accessible coil fins.'],
['case-in-situ-steam-cleaning.webp',zh?'不拆风轮原位深洗':'In-situ cleaning without blower removal',zh?'室内机和风轮保持原位，处理可接触翅片、出风口及原位风轮表面积垢。':'The indoor unit and blower stay in place while accessible fins, outlet and in-place blower surfaces are treated.'],
['case-drainage-cleaning.webp',zh?'排水盘及排水系统':'Drain pan and drainage',zh?'封闭式清理污垢，并在施工后测试排水。':'Contained removal of residue followed by drainage testing.']];return `<div class="case-grid">${items.map(i=>`<article class="case-card"><img src="${asset(i[0])}" alt="${i[1]}" width="1200" height="900" loading="lazy"><div><h3>${i[1]}</h3><p>${i[2]}</p></div></article>`).join('')}</div>`}
function faqMarkup(locale,items=faqs[locale]){return `<div class="faq-list">${items.map((f,i)=>`<article class="faq-item ${i===0?'is-open':''}"><h3><button type="button" data-faq-button aria-expanded="${i===0?'true':'false'}">${f[0]}<span>＋</span></button></h3><div class="faq-answer">${f[1]}</div></article>`).join('')}</div>`}
function pageHero(locale,route,page){const zh=locale==='zh';let image=null;if(route==='/services/')image='hero-services.webp';else if(route==='/services/high-temperature-steam-chemical-cleaning/')image='hero-steam-cleaning.webp';else if(route==='/services/steam-vs-standard-aircon-cleaning/')image='hero-steam-cleaning.webp';else if(route==='/services/why-steam-chemical-cleaning/')image='hero-contact-v2.webp';else if(route==='/services/pricing-packages/')image='pricing-consultation.webp';else if(route==='/faq-reviews/')image='hero-faq-reviews.webp';else if(route==='/faq-reviews/aircon-cleaning-faq/')image='faq-knowledge.webp';else if(route==='/faq-reviews/customer-reviews/')image='hero-contact-v2.webp';else if(route==='/faq-reviews/before-after/')image='hero-steam-cleaning.webp';else if(route==='/contact/')image='hero-contact.webp';const content=`<div class="breadcrumbs"><a href="${zh?'/zh/':'/'}">${common[locale].home}</a> / ${page.eyebrow||page.heading||page.title.split('|')[0]}</div>${page.eyebrow?`<div class="eyebrow">${page.eyebrow}</div>`:''}<h1>${page.heading||page.title.split('|')[0]}</h1>${page.lead?`<p>${page.lead}</p>`:''}<a class="button ${image?'button-ghost':'button-outline'} back-home" href="${zh?'/zh/':'/'}">← ${zh?'返回首页':'BACK TO HOME'}</a>`;return image?`<section class="page-hero page-hero-photo"><img class="page-hero-bg" src="${asset(image)}" alt="" width="1920" height="1080" fetchpriority="high"><div class="page-hero-shade"></div><div class="container page-hero-content">${content}</div></section>`:`<section class="page-hero"><div class="container">${content}</div></section>`}
function services(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'高温蒸汽空调<br><span>化学清洗服务</span>':'HIGH-TEMPERATURE STEAM<br><span>AIRCON CLEANING SERVICES</span>',lead:zh?'所有页面只围绕空调深度清洗展开，并清楚说明作用、范围、流程、对比、保修注意事项和价格。':'Every service page focuses on aircon deep cleaning, with clear scope, process, comparison, warranty considerations, suitability and pricing.'})}<section class="section"><div class="container">${serviceCards(locale)}</div></section><section class="section section-mint"><div class="container split"><div class="prose"><div class="eyebrow">${zh?'专业施工':'Professional workflow'}</div><h2>${zh?'不仅是冲洗空调。':'More than rinsing a unit.'}</h2><p>${zh?'深度清洗需要现场防护、正确拆卸、适用的化学预处理、可控蒸汽、水分控制、重新组装和运行测试。':'A proper deep clean requires work-area protection, correct dismantling, suitable chemical pre-treatment, controlled steam, moisture containment, reassembly and operational testing.'}</p><p>${zh?'设备及施工图统一使用NANOFIXAC品牌视觉；具体机器参数以最终采购设备铭牌和说明书为准。':'Equipment imagery follows the NANOFIXAC brand system. Final machine specifications should follow the purchased unit plate and manual.'}</p></div>${img('chemical-pre-treatment.webp',zh?'NANOFIXAC专业空调高温蒸汽化学清洗设备及施工现场':'NANOFIXAC professional high-temperature steam aircon chemical cleaning equipment')}</div></section></main>`}
function article(locale,page,route){return `<main id="main">${pageHero(locale,route,page)}<section class="section"><div class="container content-grid"><article class="prose"><div class="answer-box"><strong>${locale==='en'?'Short answer':'简要回答'}</strong><br>${page.answer}</div>${page.sections.map(s=>`<section><h2>${s[0]}</h2><ul class="check-list">${s[1].map(x=>`<li>${x}</li>`).join('')}</ul></section>`).join('')}</article><aside><div class="side-panel">${img(page.image,page.imageAlt)}<h3>${locale==='en'?'Related pages':'相关页面'}</h3><a href="${localPath('/services/steam-vs-standard-aircon-cleaning/',locale)}">${locale==='en'?'Steam vs standard cleaning':'蒸汽化学清洗与普通清洗'} <span>→</span></a><a href="${localPath('/services/pricing-packages/',locale)}">${locale==='en'?'Pricing & packages':'价格与套餐'} <span>→</span></a><a href="${localPath('/faq-reviews/',locale)}">${locale==='en'?'Frequently asked questions':'常见问题'} <span>→</span></a></div></aside></div></section></main>`}
function compare(locale,page,route){const zh=locale==='zh';const rows=zh?[['主要目的','日常保养','内部深度清洁'],
['过滤网','包含','包含'],
['蒸发器','基础表面清洁','更深入处理可接触翅片'],
['风轮','有限或不包含','在可接触范围内原位深洗，不拆除风轮'],
['排水盘','基础处理','清理污垢并测试排水'],
['高温蒸汽','不包含','包含'],
['施工防护','基础','使用清洗罩并保护周边'],
['适合情况','定期维护、轻微积尘','顽固积垢、异味、风量受阻'],
['施工时间','较短','较长'],
['价格','较低','根据深度和状况计算']]:[['Primary purpose','Routine maintenance','Internal deep cleaning'],
['Air filters','Included','Included'],
['Evaporator coil','Basic surface clean','Deeper treatment of accessible fins'],
['Blower wheel','Limited or excluded','Cleaned in place where accessible; not removed'],
['Drain pan','Basic treatment','Residue removal and drainage test'],
['High-temperature steam','Not included','Included'],
['Work-area protection','Basic','Wash bag and surrounding protection'],
['Best suited to','Regular upkeep and light dust','Stubborn buildup, odour or restricted airflow'],
['Working time','Shorter','Longer'],
['Price','Lower','Based on depth and condition']];return `<main id="main">${pageHero(locale,route,page)}<section class="section"><div class="container split"><div>${img(page.image,page.imageAlt)}</div><div class="prose"><div class="answer-box"><strong>${zh?'简要结论':'Short answer'}</strong><br>${zh?'普通清洗适合状态良好的空调日常保养；高温蒸汽化学清洗适合内部积垢明显、异味反复或风量受阻的空调。':'Standard servicing is suitable for routine upkeep of a clean unit. Steam chemical cleaning is intended for visible internal buildup, recurring odour or restricted airflow.'}</div></div></div></section><section class="section section-mint"><div class="container"><table class="comparison"><thead><tr><th>${zh?'对比项目':'Comparison'}</th><th>${zh?'普通空调清洗':'Standard servicing'}</th><th>${zh?'高温蒸汽化学清洗':'Steam chemical cleaning'}</th></tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section></main>`}
function pricing(locale,page,route){const zh=locale==='zh';const cards=zh?[['单台住宅空调','根据机型、状况和拆卸要求报价'],
['多台清洗套餐','根据同一地址的空调数量组合报价'],
['商业场所','根据设备清单、施工时段和现场条件报价']]:[['Single residential unit','Quoted by unit type, condition and dismantling required'],
['Multi-unit package','Combined price based on units at the same address'],
['Commercial property','Quoted by equipment schedule, work timing and site conditions']];return `<main id="main">${pageHero(locale,route,{heading:zh?'价格与清洗套餐':'PRICING & CLEANING PACKAGES',lead:zh?'在最终服务价格确认前，先把影响价格的因素和包含范围写清楚。':'We explain the factors and included scope before confirming the final service price.'})}<section class="section"><div class="container"><div class="cards">${cards.map((c,i)=>`<article class="card"><div class="number">0${i+1}</div><h3>${c[0]}</h3><p>${c[1]}</p><a class="button button-outline" href="${localPath('/contact/#booking',locale)}">${zh?'获取报价':'GET A QUOTE'}</a></article>`).join('')}</div><div class="answer-box"><strong>${zh?'价格通常取决于：':'Pricing normally depends on:'}</strong> ${zh?'室内机类型和尺寸、数量、积垢程度、施工空间、拆卸范围、是否包含室外机以及服务时间。':'indoor-unit type and size, quantity, buildup, access, dismantling scope, outdoor-unit inclusion and service timing.'}</div></div></section></main>`}
function faqPage(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'空调蒸汽清洗<br><span>常见问题</span>':'AIRCON STEAM CLEANING<br><span>FAQ & ANSWERS</span>',lead:zh?'用清楚、直接并可独立理解的答案，帮助客户和搜索系统准确了解服务。':'Clear, self-contained answers help customers and search systems understand the service accurately.'})}<section class="section"><div class="container content-grid"><div>${faqMarkup(locale)}</div><aside><div class="side-panel"><h3>${zh?'客户帮助':'Customer resources'}</h3><a href="${localPath('/faq-reviews/customer-reviews/',locale)}">${zh?'客户评论':'Customer reviews'} <span>→</span></a><a href="${localPath('/faq-reviews/before-after/',locale)}">${zh?'清洗前后案例':'Before & after'} <span>→</span></a><a href="${localPath('/services/steam-vs-standard-aircon-cleaning/',locale)}">${zh?'清洗方式对比':'Cleaning comparison'} <span>→</span></a></div></aside></div></section></main>`}
function reviews(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'客户评论':'CUSTOMER REVIEWS',lead:zh?'评论内容只在能够核实来源后发布，避免使用虚构评分或样板评价。':'Customer feedback is published only after its source can be verified. We do not present sample copy as a genuine review.'})}<section class="section"><div class="container"><div class="review-placeholder"><h2>${zh?'评论接口预留区':'Review integration area'}</h2><p>${zh?'正式上线前可连接NANOFIX的Google商家资料，显示客户评分、评论内容和原始链接。':'Before public launch, this area can connect to NANOFIX’s Google Business Profile and display customer ratings, review text and source links.'}</p><p>${zh?'建议字段：客户名称或简称、物业类型、服务项目、服务日期、评分、评论内容和Google原始链接。':'Recommended fields: customer name or initials, property type, service, date, rating, review text and original Google link.'}</p></div><div class="review-home-action"><a class="button button-outline" href="${localPath('/',locale)}">${zh?'← 返回首页':'← BACK TO HOME'}</a></div></div></section></main>`}
function cases(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'清洗前后<br><span>部件案例</span>':'BEFORE & AFTER<br><span>CLEANING CASES</span>',lead:zh?'按照蒸发器、风轮和排水系统分别展示，让客户看清服务具体处理哪些位置。':'Organised by coil, blower and drainage so customers can see exactly what the service addresses.'})}<section class="section"><div class="container">${caseCards(locale)}</div></section><section class="section section-mint"><div class="container split">${img('commercial-steam-cleaning.webp',zh?'新加坡办公室多台空调高温蒸汽化学清洗':'High-temperature steam chemical cleaning of multiple aircon units in a Singapore office')}<div class="prose"><div class="eyebrow">${zh?'商业场所案例':'Commercial cleaning'}</div><h2>${zh?'分阶段施工，减少营业影响。':'Planned in stages to reduce disruption.'}</h2><p>${zh?'商业项目可根据设备数量、营业时间和现场通行安排分区施工，并在每个区域完成后进行运行检查。':'Commercial work can be staged around equipment quantity, operating hours and access, with operational checks completed by zone.'}</p></div></div></section></main>`}
function contact(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'预约高温蒸汽<br><span>空调化学清洗</span>':'BOOK HIGH-TEMPERATURE STEAM<br><span>AIRCON CHEMICAL CLEANING</span>',lead:zh?'填写资料后，系统会整理成WhatsApp咨询信息，由客户确认后发送。':'Complete the form and we will prepare a WhatsApp enquiry for you to review and send.'})}<section class="section" id="booking"><div class="container contact-grid"><aside class="contact-panel"><div class="eyebrow" style="color:#75d7a8">NANOFIX PTE. LTD.</div><h2>${zh?'最快联系方式：WhatsApp':'Fastest response: WhatsApp'}</h2><a href="https://wa.me/${phoneRaw}" target="_blank" rel="noopener noreferrer">↗ ${phone}</a><a href="mailto:nanofixac@gmail.com">✉ nanofixac@gmail.com</a><p>16 Raffles Quay #41-01<br>Hong Leong Building<br>Singapore 048581</p><p>UEN 202539469C</p></aside><form class="form" data-booking-form><input type="hidden" name="locale" value="${locale}"><div class="form-grid"><div class="field"><label for="name">${zh?'姓名':'Name'}</label><input id="name" name="name" required autocomplete="name" maxlength="120"></div><div class="field"><label for="mobile">${zh?'手机／WhatsApp':'Mobile / WhatsApp'}</label><input id="mobile" name="mobile" required inputmode="tel" autocomplete="tel" maxlength="40"></div><div class="field"><label for="email">${zh?'电邮（选填）':'Email (optional)'}</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254"></div><div class="field"><label for="postal_code">${zh?'邮编':'Postal code'}</label><input id="postal_code" name="postal_code" inputmode="numeric" autocomplete="postal-code" maxlength="12"></div><div class="field"><label for="property_type">${zh?'房屋类型':'Property type'}</label><select id="property_type" name="property_type"><option>${zh?'公寓':'Condominium'}</option><option>HDB</option><option>${zh?'有地住宅':'Landed property'}</option><option>${zh?'商业场所':'Commercial property'}</option></select></div><div class="field"><label for="unit_count">${zh?'空调数量':'Number of units'}</label><input id="unit_count" name="unit_count" type="number" min="1" max="100" value="1"></div><div class="field"><label for="preferred_date">${zh?'希望日期':'Preferred date'}</label><input id="preferred_date" name="preferred_date" type="date"></div><div class="field full"><label for="details">${zh?'空调目前的问题':'What is happening with the aircon?'}</label><textarea id="details" name="details" maxlength="5000" placeholder="${zh?'例如：有异味、风量下降、很久没有深度清洗':'For example: musty odour, weak airflow, long time since last deep clean'}"></textarea></div><div class="field full consent-field"><label><input type="checkbox" name="pdpa_consent" required> ${zh?'我同意NANOFIX使用以上资料回复本次咨询。':'I agree that NANOFIX may use these details to respond to this enquiry.'}</label></div><div class="field full"><button class="button button-orange" type="submit">${zh?'生成WHATSAPP咨询信息':'PREPARE WHATSAPP ENQUIRY'} →</button><div class="form-message" data-form-message hidden>${zh?'WhatsApp将打开，请检查内容后发送。':'WhatsApp will open. Please review the message before sending.'}</div></div></div></form></div></section></main>`}
function legal(locale,page,route){const zh=locale==='zh',privacy=route==='/privacy/';return `<main id="main">${pageHero(locale,route,{heading:privacy?(zh?'隐私政策':'PRIVACY POLICY'):(zh?'服务条款':'TERMS OF SERVICE'),lead:zh?'最后更新：2026年9月8日':'Last updated: 8 September 2026'})}<section class="section"><div class="container prose legal">${privacy?`<h2>${zh?'我们收集的资料':'Information we collect'}</h2><p>${zh?'当您提交咨询时，我们可能收集姓名、电话号码、邮编、房屋类型、空调数量、希望日期和问题说明。':'When you submit an enquiry, we may collect your name, telephone number, postal code, property type, unit quantity, preferred date and issue description.'}</p><h2>${zh?'资料用途':'How information is used'}</h2><p>${zh?'资料用于回复咨询、准备报价、安排服务和保留必要的业务记录。网站不会要求您输入付款密码或银行登录资料。':'Information is used to respond, prepare quotations, arrange services and maintain necessary business records. This website does not ask for payment passwords or banking login details.'}</p><h2>${zh?'联系我们':'Contact'}</h2><p>nanofixac@gmail.com · ${phone}</p>`:`<h2>${zh?'报价与服务范围':'Quotations and scope'}</h2><p>${zh?'最终价格、清洗范围、施工时间和任何质保以NANOFIX正式报价或工作确认单为准。':'Final pricing, cleaning scope, timing and any warranty are governed by NANOFIX’s formal quotation or work confirmation.'}</p><h2>${zh?'现场条件':'Site conditions'}</h2><p>${zh?'客户应提供合理、安全的施工通道，并提前说明已知故障、维修记录或受限区域。':'Customers should provide reasonable, safe access and disclose known faults, repair history or restricted areas.'}</p><h2>${zh?'清洗限制':'Cleaning limitations'}</h2><p>${zh?'空调清洗不能替代机械、电气或制冷系统维修。需要额外工作的故障会另行说明。':'Aircon cleaning does not replace mechanical, electrical or refrigeration-system repair. Faults requiring additional work will be explained separately.'}</p>`}</div></section></main>`}

function faqPageV2(locale,page,route){const zh=locale==='zh';const resources=zh?[['faq-knowledge.webp','专业问答知识库','直接解答免大拆、风轮原位清洗、化学去污、高温蒸汽杀菌除味、保修、施工时间和价格。',['室内机和风轮需要拆下来吗？','高温蒸汽如何帮助杀菌除味？','化学清洗与普通保养有什么不同？'],'/faq-reviews/aircon-cleaning-faq/'],['hero-contact-v2.webp','客户评论','展示客户反馈、服务项目、物业类型及原始评论链接；正式上线前不使用未经授权的评论。',['住宅与商业项目分开整理','标明实际服务项目与日期','保留原始平台链接'],'/faq-reviews/customer-reviews/'],['case-in-situ-steam-cleaning.webp','不拆风轮清洗案例','按蒸发器、原位风轮与出风口、排水盘及排水系统分类展示，说明每张图片对应的施工位置。',['室内机保持在墙上','风轮不拆下','清洗罩封闭收集污水'],'/faq-reviews/before-after/']]:[['Aircon cleaning knowledge base','faq-knowledge.webp','Straight answers on no major dismantling, in-place blower cleaning, chemical soil removal, steam sanitising and odour removal, warranty, timing and pricing.',['Must the indoor unit or blower be removed?','How does steam help sanitise and remove odour?','How is this different from routine servicing?'],'/faq-reviews/aircon-cleaning-faq/'],['Customer reviews','hero-contact-v2.webp','Customer feedback is organised by service type, property context and original source links; unauthorised or invented testimonials are not used.',['Residential and commercial feedback','Actual service type and date','Original platform source link'],'/faq-reviews/customer-reviews/'],['In-situ cleaning cases','case-in-situ-steam-cleaning.webp','Examples are organised by evaporator coil, in-place blower and outlet, drain pan and drainage, with the treated area clearly explained.',['Indoor unit stays wall-mounted','Blower wheel stays in place','Wash bag contains the runoff'],'/faq-reviews/before-after/']];const normalized=zh?resources:resources.map(r=>[r[1],r[0],r[2],r[3],r[4]]);return `<main id="main">${pageHero(locale,route,{heading:zh?'常见问题、评论<br><span>与清洗案例</span>':'FAQ, REVIEWS<br><span>& CLEANING CASES</span>',lead:zh?'每个栏目横向展开，向下浏览即可快速查看重点内容；点击“查看更多”进入完整页面。':'Each resource opens across the page. Scroll down for highlights, then choose “View more” for the full page.'})}<section class="section"><div class="container resource-stack">${normalized.map((r,i)=>`<article class="resource-row ${i%2?'resource-row-reverse':''}"><img src="${asset(r[1])}" alt="${r[0]}" width="1200" height="750" loading="lazy"><div class="resource-copy"><div class="eyebrow">0${i+1}</div><h2>${r[0]}</h2><p>${r[2]}</p><ul class="check-list">${r[3].map(x=>`<li>${x}</li>`).join('')}</ul><a class="button button-green" href="${localPath(r[4],locale)}">${zh?'查看更多':'VIEW MORE'} →</a></div></article>`).join('')}</div></section></main>`}
function faqDetail(locale,page,route){const zh=locale==='zh';return `<main id="main">${pageHero(locale,route,{heading:zh?'高温蒸汽空调清洗<br><span>详细问答</span>':'HIGH-TEMPERATURE STEAM AIRCON CLEANING<br><span>DETAILED FAQ</span>',lead:zh?'每个答案可独立理解，方便客户快速查找，也有利于Google与AI问答系统准确提取。':'Every answer is self-contained for customers, Google search and AI answer engines.'})}<section class="section"><div class="container content-grid"><div>${faqMarkup(locale)}</div><aside><div class="side-panel">${img('protected-workflow.webp',zh?'NANOFIXAC安全防护施工流程':'NANOFIXAC protected cleaning workflow')}<h3>${zh?'快速返回':'Quick links'}</h3><a href="${localPath('/faq-reviews/',locale)}">${zh?'问答、评论与案例总览':'FAQ, reviews and cases'} <span>→</span></a><a href="${localPath('/',locale)}">${zh?'返回首页':'Back to home'} <span>→</span></a></div></aside></div></section></main>`}
function casesV2(locale,page,route){let html=cases(locale,page,route);return html.replace('清洗前后<br><span>部件案例</span>','清洗前后<br><span>原位深洗案例</span>').replace('BEFORE & AFTER<br><span>CLEANING CASES</span>','BEFORE & AFTER<br><span>IN-SITU CLEANING CASES</span>').replace('按照蒸发器、风轮和排水系统分别展示，让客户看清服务具体处理哪些位置。','按照蒸发器、原位风轮与出风口、排水系统分别展示；室内机和风轮不拆下。').replace('Organised by coil, blower and drainage so customers can see exactly what the service addresses.','Organised by coil, in-place blower and outlet, and drainage. The indoor unit and blower wheel are not removed.');return html}
