function faqPageFinal(locale,page,route){let html=faqPageV2(locale,page,route);const pairs=locale==='zh'?[['专业问答知识库','faq-knowledge.webp'],['客户评论','hero-contact-v2.webp'],['不拆风轮清洗案例','case-in-situ-steam-cleaning.webp']]:[['Aircon cleaning knowledge base','faq-knowledge.webp'],['Customer reviews','hero-contact-v2.webp'],['In-situ cleaning cases','case-in-situ-steam-cleaning.webp']];for(const [title,file] of pairs){html=html.replace(`src="${asset(title)}" alt="${file}"`,`src="${asset(file)}" alt="${title}"`)}return html}
