function homeV2Final(locale){
  const zh=locale==='zh'; let html=homeV2(locale);
  const benefits=zh?[
    ['免大拆，不影响整机原厂质保','室内机保持在墙上，风轮保持原位；只拆过滤网、外盖和必要面板，避免改动密封制冷系统。'],
    ['化学清洗顽固污垢','适用的空调化学清洗剂帮助分解翅片、原位风轮、出风口和排水盘上的油膜、灰尘及有机积垢。'],
    ['高温蒸汽杀菌除味','高温蒸汽直接处理可接触表面；在适当温度与接触时间下，有助于杀灭细菌、降低霉菌污染并祛除异味。'],
    ['专业防护与清洗后测试','施工前保护墙面、地面和家具，清洗后检查风量、排水和运行状态，适合公寓、别墅及办公室。']
  ]:[
    ['No major dismantling — designed to preserve the original manufacturer warranty','The indoor unit stays wall-mounted and the blower wheel remains in place. Only filters, covers and necessary panels are removed.'],
    ['Chemical cleaning for stubborn grime','A suitable aircon chemical cleaner loosens oily film, embedded dust and organic buildup on the coil, in-place blower, outlet and drain pan.'],
    ['High-temperature steam sanitises and removes odour','Steam treats accessible surfaces directly and, with suitable heat and contact time, helps kill bacteria, reduce mould contamination and remove odour.'],
    ['Protected work and post-clean testing','Walls, floors and furniture are protected before work, then airflow, drainage and operation are checked for condos, landed homes and offices.']
  ];
  const start=html.indexOf('<div class="benefit-grid">'); const marker='</div></div></section><section class="section section-navy">'; const end=html.indexOf(marker,start);
  if(start>=0&&end>=0) html=html.slice(0,start)+`<div class="benefit-grid">${benefits.map((b,i)=>`<article class="benefit-card"><span>0${i+1}</span><h3>${b[0]}</h3><p>${b[1]}</p></article>`).join('')}</div>`+html.slice(end);
  html=html.replace(zh?'三项核心好处，<br>直接说明。':'Three core benefits,<br>clearly explained.',zh?'四项核心好处，<br>直接说明。':'Four core benefits,<br>clearly explained.');
  const oldAlt=zh?'NANOFIXAC技术人员在清洗后检查空调':'NANOFIXAC technician inspecting an aircon after cleaning';
  html=html.replace(`src="${asset('post-clean-inspection.webp')}" alt="${oldAlt}"`,`src="${asset('faq-knowledge.webp')}" alt="${oldAlt}"`);
  const oldTrust=zh?'<span>免大拆</span><span>卫生深洗</span><span>清洗后测试</span>':'<span>No major dismantling</span><span>Hygiene-focused</span><span>Post-clean testing</span>';
  const newTrust=zh?'<span>免大拆，不影响整机原厂质保</span><span>化学清洗，去除顽固污垢</span><span>高温蒸汽，杀菌除味</span>':'<span>No major dismantling — designed to preserve the original manufacturer warranty</span><span>Chemical cleaning removes stubborn grime</span><span>High-temperature steam sanitises and removes odour</span>';
  html=html.replace(oldTrust,newTrust);
  const faqFive=faqMarkup(locale,faqs[locale].slice(0,5));
  const faqThree=faqMarkup(locale,faqs[locale].slice(0,3));
  const faqMore=`<a class="faq-more-row" href="${localPath('/faq-reviews/',locale)}"><span>${zh?'更多问题':'More questions'}</span><span>${zh?'查看全部问题 →':'View all questions →'}</span></a>`;
  html=html.replace(faqFive,`${faqThree}${faqMore}`);
  return html;
}

