fs.writeFileSync(path.join(out,'assets','content-manifest.json'),JSON.stringify({version:2,locale_default:'en-SG',locales:['en-SG','zh-SG'],company:{name:'NANOFIX PTE. LTD.',uen:'202539469C',phone,email:'nanofixac@gmail.com'},routes,booking_fields:['name','mobile','postal_code','property_type','unit_count','preferred_date','details']},null,2));
